### Task 3: Typed API client

**Files:**
- Create: `dashboard/src/api/client.ts`, `dashboard/src/api/client.test.ts`, `dashboard/src/api/types.ts`, `dashboard/src/api/{zones,tasks,goals,violations,pushSubscriptions,pings,users}.ts`
- Modify: `dashboard/src/auth/AuthContext.tsx` (refactor its own three `fetch` calls to keep using plain `fetch`, since the client's auth header injection would be circular for login/refresh themselves — but expose `accessToken` in a way `client.ts` can read it)
- Modify: `dashboard/package.json` (add `vitest`, `@testing-library/react` if needed for the two logic tests — check if plain vitest + `fetch` mocking is enough before reaching for RTL; it likely is, since neither test renders a component)

**Interfaces:** per the plan header's Interfaces summary.

- [ ] **Step 1: Install vitest**

```bash
cd /Users/taha/Documents/atlas-fieldforce/dashboard
npm install -D vitest
```

Add a `test` script to `package.json`: `"test": "vitest run"`.

- [ ] **Step 2: Decide how `client.ts` reads the current access token without a circular import on `AuthContext`**

`AuthContext` needs `client.ts` (to make authenticated calls once the app is past login), but `client.ts` also needs to know the current access token, which lives in `AuthContext`'s React state — a plain module can't read React state directly. Resolve this with a tiny module-level mutable holder that `AuthContext` writes to on every token change and `client.ts` reads from — NOT a second source of truth, just a synchronous mirror of the same value:

```ts
// dashboard/src/auth/tokenStore.ts
let currentAccessToken: string | null = null
let currentRefreshToken: string | null = null

export function setTokens(access: string | null, refresh: string | null) {
  currentAccessToken = access
  currentRefreshToken = refresh
}

export function getAccessToken(): string | null {
  return currentAccessToken
}

export function getRefreshToken(): string | null {
  return currentRefreshToken
}
```

Update `AuthContext.tsx` to call `setTokens(...)` everywhere it currently calls `setAccessToken(...)` / touches `localStorage` for the refresh token, so `tokenStore` always mirrors the current session. This is a small refactor of Task 2's file, not a rewrite — read the current file first.

- [ ] **Step 3: Write the failing test for the refresh-retry-once behavior**

```ts
// dashboard/src/api/client.test.ts
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { setTokens } from '../auth/tokenStore'

describe('apiFetch 401 handling', () => {
  beforeEach(() => {
    setTokens('old-access-token', 'a-refresh-token')
    vi.restoreAllMocks()
  })

  it('refreshes once and retries once on a 401, then succeeds', async () => {
    const responses = [
      new Response(null, { status: 401 }),
      new Response(JSON.stringify({ access_token: 'new-access-token', refresh_token: 'new-refresh-token' }), { status: 200 }),
      new Response(JSON.stringify({ ok: true }), { status: 200 }),
    ]
    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
    vi.stubGlobal('fetch', fetchMock)

    const { apiFetch } = await import('./client')
    const result = await apiFetch<{ ok: boolean }>('/api/v1/zones')

    expect(result).toEqual({ ok: true })
    expect(fetchMock).toHaveBeenCalledTimes(3)
    // second call must be the refresh endpoint
    expect(fetchMock.mock.calls[1][0]).toContain('/api/v1/auth/refresh')
  })

  it('does not loop -- a second consecutive 401 after refresh throws instead of retrying again', async () => {
    const responses = [
      new Response(null, { status: 401 }),
      new Response(JSON.stringify({ access_token: 'new-access-token', refresh_token: 'new-refresh-token' }), { status: 200 }),
      new Response(null, { status: 401 }),
    ]
    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
    vi.stubGlobal('fetch', fetchMock)

    const { apiFetch } = await import('./client')

    await expect(apiFetch('/api/v1/zones')).rejects.toThrow()
    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it('when the refresh call itself fails, clears tokens and throws without retrying the original request', async () => {
    const responses = [
      new Response(null, { status: 401 }),
      new Response(null, { status: 401 }), // refresh itself fails
    ]
    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
    vi.stubGlobal('fetch', fetchMock)

    const { apiFetch } = await import('./client')
    const { getAccessToken } = await import('../auth/tokenStore')

    await expect(apiFetch('/api/v1/zones')).rejects.toThrow()
    expect(fetchMock).toHaveBeenCalledTimes(2)
    expect(getAccessToken()).toBeNull()
  })
})
```

